enum SsAbiStatus : int32_t {
  SS_ABI_OK = 0,
  SS_ABI_NULL_POINTER = 1,
  SS_ABI_BAD_COUNT = 2,
  SS_ABI_VERSION_MISMATCH = 3,
  SS_ABI_STRUCT_SIZE_MISMATCH = 4,
  SS_ABI_INTERNAL_ERROR = 5
};

struct SsAbiQuarterWitness {
  uint32_t offset;
  uint32_t size;
  uint64_t local_mask;
};

struct SsAbiWitness {
  uint32_t abi_version;
  uint32_t struct_size;
  uint8_t present;
  uint8_t reserved0;
  uint16_t reserved1;
  uint32_t reserved2;
  SsAbiQuarterWitness q0;
  SsAbiQuarterWitness q1;
  SsAbiQuarterWitness q2;
  SsAbiQuarterWitness q3;
  uint64_t verified_sum_low64;
};

struct SsAbiBudget {
  uint32_t abi_version;
  uint32_t struct_size;
  uint64_t memory_cap_bytes;
  uint64_t time_budget_ns;
  uint64_t heap_pop_budget;
  uint64_t heap_push_budget;
  uint64_t pair_candidate_budget;
  uint32_t max_quarter_bits;
  uint32_t max_batch_gaps;
  uint64_t max_quarter_sums;
  uint8_t allow_unsat_completion;
  uint8_t shared_batch_search_budget;
  uint16_t reserved0;
  uint32_t reserved1;
};

struct SsAbiQueryResult {
  uint32_t abi_version;
  uint32_t struct_size;
  int32_t result;
  int32_t unknown_reason;
  SsAbiWitness witness;
  uint64_t elapsed_ns;
  uint64_t memory_peak_bytes;
  uint64_t memory_estimated_bytes;
  uint64_t memory_safety_margin_bytes;
  uint64_t quarter_sum_bytes;
  uint64_t heap_bytes;
  uint64_t quarter_sums_generated;
  uint64_t quarter_generate_ns;
  uint64_t quarter_sort_ns;
  uint64_t heap_pushes;
  uint64_t heap_pops;
  uint64_t pair_candidates_inspected;
  uint64_t search_ns;
  uint64_t witness_verify_failures;
};

