struct Table {
  int32_t index = 0;
  int32_t remaining = 0;
  TableMode mode = TableMode::DUAL;
  SumDtype dtype = SumDtype::I64;
  int32_t cached_start = 0;
  int32_t cached_count = 0;
  int32_t streamed_start = 0;
  int32_t streamed_count = 0;
  std::vector<int64_t> left_i64;
  std::vector<int64_t> right_i64;
  std::vector<uint32_t> left_u32;
  std::vector<uint32_t> right_u32;
  std::vector<uint64_t> left_u64;
  std::vector<uint64_t> right_u64;
  std::vector<uint64_t> bloom_bits;
  uint64_t bloom_block_count = 0;
  bool bloom_ready = false;
  bool bloom_build_attempted = false;
  uint64_t table_query_count = 0;
  uint64_t direct_binary_search_calls = 0;
  uint64_t direct_stream_probes = 0;
  uint64_t lazy_bloom_promotions = 0;
  uint8_t bloom_num_hashes = 0;
  uint32_t bloom_bits_per_key = 0;
  bool bucket_lazy_ready = false;
  int32_t bucket_lazy_bits = 0;
  uint32_t bucket_lazy_active_bits = 0;
  uint32_t bucket_lazy_count = 0;
  uint32_t bucket_lazy_shift = 0;
  uint32_t bucket_lazy_useful_bits = 0;
  uint64_t bucket_lazy_max_value = 0;
  std::vector<size_t> bucket_offsets;
  std::vector<uint8_t> bucket_sorted;
  std::vector<uint8_t> bucket_touched;

  uint64_t bytes() const {
    const uint64_t bloom_bytes = static_cast<uint64_t>(bloom_bits.size()) *
                                 static_cast<uint64_t>(sizeof(uint64_t));
    const uint64_t bucket_meta_bytes =
        static_cast<uint64_t>(bucket_offsets.size()) *
            static_cast<uint64_t>(sizeof(size_t)) +
        static_cast<uint64_t>(bucket_sorted.size()) *
            static_cast<uint64_t>(sizeof(uint8_t)) +
        static_cast<uint64_t>(bucket_touched.size()) *
            static_cast<uint64_t>(sizeof(uint8_t));
    if (dtype == SumDtype::U32) {
      return bloom_bytes + bucket_meta_bytes +
             static_cast<uint64_t>(left_u32.size() + right_u32.size()) *
                 static_cast<uint64_t>(sizeof(uint32_t));
    }
    if (dtype == SumDtype::U64) {
      return bloom_bytes + bucket_meta_bytes +
             static_cast<uint64_t>(left_u64.size() + right_u64.size()) *
                 static_cast<uint64_t>(sizeof(uint64_t));
    }
    return bloom_bytes + bucket_meta_bytes +
           static_cast<uint64_t>(left_i64.size() + right_i64.size()) *
               static_cast<uint64_t>(sizeof(int64_t));
  }

  uint64_t entry_count() const {
    if (dtype == SumDtype::U32) {
      return static_cast<uint64_t>(left_u32.size() + right_u32.size());
    }
    if (dtype == SumDtype::U64) {
      return static_cast<uint64_t>(left_u64.size() + right_u64.size());
    }
    return static_cast<uint64_t>(left_i64.size() + right_i64.size());
  }
};

