  template <typename SumT>
  void query_stream_unsigned_table_many_no_bloom(
      const TableHandle &table, const std::vector<SumT> &cached_sums,
      const std::vector<QueryPlanItem> &plan_items, int32_t *out_results) {
    constexpr size_t kChunkSize = 16;
    add_stat(&stats.stream_queries, static_cast<uint64_t>(plan_items.size()));
    add_stat(&stats.no_bloom_batch_queries,
             static_cast<uint64_t>(plan_items.size()));
    std::vector<uint8_t> resolved(plan_items.size(), 0);
    for (size_t chunk_begin = 0; chunk_begin < plan_items.size();
         chunk_begin += kChunkSize) {
      const size_t chunk_end =
          std::min(chunk_begin + kChunkSize, plan_items.size());
      uint64_t unresolved_count =
          static_cast<uint64_t>(chunk_end - chunk_begin);
      bool overflow = false;
      uint64_t generated = 0;
      uint64_t exact_lookups = 0;
      uint64_t exact_hits = 0;
      stats.exists_many_chunks += 1;
      stats.exists_many_stream_passes += 1;
      stats.no_bloom_batch_streams += 1;
      stats.no_bloom_batch_stream_passes += 1;
      stream_unsigned_many_dfs(table, 0, uint64_t{0}, cached_sums, plan_items,
                               chunk_begin, chunk_end, &resolved, out_results,
                               &unresolved_count, &overflow, &generated,
                               &exact_lookups, &exact_hits);
      add_stat(&stats.stream_sums_generated, generated);
      add_stat(&stats.direct_stream_probes, generated);
      add_stat(&stats.binary_search_calls, exact_lookups);
      add_stat(&stats.direct_binary_search_calls, exact_lookups);
      add_stat(&stats.no_bloom_batch_exact_lookups, exact_lookups);
      add_stat(&stats.exact_hits, exact_hits);
      add_stat(&stats.no_bloom_batch_hits, exact_hits);
      if (overflow) {
        continue;
      }
      for (size_t i = chunk_begin; i < chunk_end; ++i) {
        if (!resolved[i]) {
          out_results[plan_items[i].original_pos] = SSP_RESULT_UNSAT;
          resolved[i] = 1;
          stats.no_bloom_batch_unsats += 1;
        }
      }
    }
  }

